// P3 gate (Doc 10): context-blind accuracy ≤ 20 % on 500 generated matrices; every rule-based item
// KEY_CONFIRMED by the independent solver; distractors engine-generated by fair_tree.
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { contextBlindMatrix, createRng, fairTree, solveMatrix, type MatrixCell, type MatrixPuzzle, type MatrixRule } from '@cognimetric/core';
import { loadPlugin } from '../src/plugins/registry';
import { resolveLevers } from '../src/engine/levers';
import { ROOT } from '../src/config';

describe('visual pipeline gate', () => {
  it('500 matrices: solver-confirmed, context-blind ≤ 20 %', async () => {
    const p = await loadPlugin(path.join(ROOT, 'plugins', 'executive'));
    const tt = p.taskTypes.get('matrix_completion')!;
    let n = 0, cbHits = 0, confirmed = 0;
    for (let i = 0; n < 500 && i < 900; i++) {
      const theta = -1.5 + (4 * (i % 9)) / 8;
      const levers = resolveLevers(p.manifest, tt.def, theta, createRng(i));
      const [item] = tt.author!({ taskType: tt.def, levers, count: 1, seed: 1000 + i, locale: 'en', readingLevel: 'grade_5', exclusionSignatures: [] }, {});
      const bp = item!.blueprint as unknown as { puzzle: MatrixPuzzle; rule: MatrixRule; options: { items: MatrixCell[] } };
      const key = bp.options.items[(item!.answer_key as { value: number }).value]!;
      const ft = fairTree(bp.puzzle, bp.rule, key, Number(levers.option_count), createRng(i + 7), levers.distractor_distance === 'far' ? 2 : 1);
      if (!ft) continue;
      n++;
      if (solveMatrix({ puzzle: bp.puzzle, rule: bp.rule, options: ft.options, keyIndex: ft.keyIndex }).verdict === 'key_confirmed') confirmed++;
      cbHits += contextBlindMatrix(ft.options)[ft.keyIndex]!;
    }
    expect(n).toBe(500);
    expect(confirmed).toBe(500);
    const rate = cbHits / n;
    console.log(`context-blind accuracy on ${n} matrices: ${(100 * rate).toFixed(1)} %`);
    expect(rate).toBeLessThanOrEqual(0.2);
  });
});
